INSERT INTO `announcement` (`id`, `app_id`, `title`, `tag`, `banner_url`, `content`, `priority`, `publish_time`, `status`, `server`, `create_time`, `update_time`) VALUES
(1001, 1, '【热】《九州》1.1.0 盛世公测版本重磅上线通知', 2, 'https://images.unsplash.com/photo-1542751371-adc38448a05e?w=800&auto=format&fit=crop&q=60', '尊敬的主公：\n《九州》1.1.0 公测新版本现已正式下发！本次更新包含全新神将【吕布】限时招募池、跨服国战【问鼎中原】系统以及海量公测好礼！详情请在活动中心查看。', 99, 1753178400000, 1, 'all', 1753142400000, 1753142400000),
(1002, 1, '【维】7月23日 全服停机维护与优化公告', 3, '', '为了提供更稳定的游戏体验，我们将于 2026-07-23 02:00-05:00 对全服进行停机维护更新，维护期间无法登录游戏。维护完成后将发放元宝*500作为安民补偿。', 90, 1753176600000, 1, 'all', 1753140600000, 1753140600000),
(1003, 1, '【新】暑期盛典·七日签到送神级武将', 1, 'https://images.unsplash.com/photo-1511512578047-dfb367046420?w=800&auto=format&fit=crop&q=60', '活动期间，每日登录游戏签到即可领取豪华礼包！第 7 天更可直接获得 SSR 武将【关羽】碎片及招募券！', 85, 1753113600000, 1, 'all', 1753084800000, 1753084800000),
(1004, 1, '九州1服 - 群雄逐鹿 临时扩容与网络提升', 0, '', '由于 1 服玩家热情爆棚，我们已完成对 1 服服务器硬件设施的紧急扩容，承载上限提升至 3000 人。', 70, 1753042800000, 1, 's1001', 1753014000000, 1753014000000),
(1005, 1, '【新】防沉迷系统升级与实名认证指引', 1, '', '根据相关规定，游戏已接入最新防沉迷验证系统。请各位玩家尽快前往设置页面完成实名登记，以免影响游戏收益。', 65, 1752943200000, 1, 'all', 1752926400000, 1752926400000),
(1006, 1, '【维】九州4服 紧急网络波动排查及修复', 3, '', '针对九州4服部分玩家出现的丢包掉线问题，机房工程师已完成线路切换。对此造成的不便深表歉意。', 60, 1752882000000, 1, 's1004', 1752847200000, 1752847200000),
(1007, 1, '草稿：八月军团合纵连横战术赛事预告', 1, '', '（运营草稿）八月将开启军团跨服联赛，冠军军团将获得专属军团旗帜与城池外显称号！', 50, 1752846000000, 0, 'all', 1752811200000, 1752811200000),
(1008, 1, '【热】首充双倍返利重置与绝版坐骑上架', 2, 'https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=800&auto=format&fit=crop&q=60', '全服首充双倍赠送额度重置！充值任意金额即可赠送绝版坐骑【赤兔马】与神兵进阶石。', 45, 1752746400000, 1, 'all', 1752710400000, 1752710400000),
(1009, 1, '外挂与非法脚本惩治特别公告（第3期）', 0, '', '官方始终对任何使用脚本、加速器及作弊行为保持零容忍态度。本次共查封违规账号 142 个，名单见附表。', 40, 1752699000000, 1, 'all', 1752648600000, 1752648600000),
(1010, 1, '已下架：六月端午龙舟安民特别活动归档', 0, '', '端午特别活动已圆满结束，感谢诸位主公热情参与。活动代币已自动转化为同等铜钱。', 10, 1750780800000, 2, 'all', 1750780800000, 1750780800000),
(1011, 1, '【新】新手主公成长基金限时开启', 1, '', '购买成长基金，达标即可获得最高 1000% 比例的元宝返还，助您开荒无忧！', 35, 1752667200000, 1, 'all', 1752624000000, 1752624000000),
(1012, 1, '九州2服 - 问鼎中原 攻城战奖励发放通知', 0, '', '本周【问鼎中原】攻城战已顺利结算，首占洛阳的军团奖励已通过系统邮件下发至成员邮箱。', 30, 1752616800000, 1, 's1002', 1752537600000, 1752537600000),
(1013, 1, '社区创作者征集计划：撰写攻略赢专属礼包', 0, '', '欢迎前往官方论坛发表阵营搭配与武将培养攻略，优秀创作者可获得游戏内专属称号【智囊】！', 25, 1752400800000, 1, 'all', 1752364800000, 1752364800000),
(1014, 1, '草稿：七夕鹊桥相会限时情缘活动说明', 1, '', '（待审核）七夕节特别活动策划分案，包含情缘副本与限时双人坐骑。', 20, 1752256800000, 0, 'all', 1752242400000, 1752242400000),
(1015, 1, '游戏客户端安全更新与防篡改补丁下发', 0, '', '已为各平台客户端热更新全服安全反作弊补丁，请保持网络通畅自动下载。', 15, 1752051600000, 1, 'all', 1752019200000, 1752019200000)
